  scrim: AppColorsLight.scrimOverlay,
  shadow: Color(0xFF000000),
  surfaceTint: Color(0x00000000),
);

/// Button variants from SPEC §1. Min size follows density (48 mobile).
abstract final class AppButtons {
  static ButtonStyle _filled(Color bg, Color fg, double h) => FilledButton.styleFrom(
    backgroundColor: bg,
    foregroundColor: fg,
    minimumSize: Size(64, h),
    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(AppRadius.sm)),
  );
  static double _h(BuildContext c) =>
      Theme.of(c).visualDensity == VisualDensity.compact ? AppDensity.compact.controlMd : AppDensity.tapMin;
  static ButtonStyle success(BuildContext c) => _filled(c.tradeColors.profit, Theme.of(c).colorScheme.onPrimary, _h(c));
  static ButtonStyle danger(BuildContext c) => _filled(c.tradeColors.loss, Theme.of(c).colorScheme.onError, _h(c));

  /// Only for actions that move REAL SOL.
  static ButtonStyle real(BuildContext c) => _filled(c.tradeColors.real, c.tradeColors.onReal, _h(c));
  static ButtonStyle secondary(BuildContext c) => OutlinedButton.styleFrom(
    minimumSize: Size(64, _h(c)),
    side: BorderSide(color: Theme.of(c).colorScheme.outline),
    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(AppRadius.sm)),
  );
  static ButtonStyle ghost(BuildContext c) => TextButton.styleFrom(minimumSize: Size(64, _h(c)));
}

abstract final class AppTheme {
  static ThemeData dark({bool compact = false}) {
    const cs = _darkScheme;
    final den = compact ? AppDensity.compact : AppDensity.comfortable;
    final shape = RoundedRectangleBorder(borderRadius: BorderRadius.circular(AppRadius.sm));
    return ThemeData(
      colorScheme: cs,
      scaffoldBackgroundColor: AppColorsDark.bgCanvas,
      textTheme: AppText.theme(AppColorsDark.textPrimary, compact: compact),
      materialTapTargetSize: compact ? MaterialTapTargetSize.shrinkWrap : MaterialTapTargetSize.padded,
      visualDensity: compact ? VisualDensity.compact : VisualDensity.standard,
      extensions: const <ThemeExtension<dynamic>>[TradeColors.dark],
      cardTheme: CardThemeData(
        color: cs.surfaceContainer,
        elevation: 0,
        surfaceTintColor: const Color(0x00000000),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.md),
          side: const BorderSide(color: AppColorsDark.borderSubtle),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(minimumSize: Size(64, den.controlLg), shape: shape),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          minimumSize: Size(64, den.controlLg),
          shape: shape,
          side: const BorderSide(color: AppColorsDark.borderStrong),
        ),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(minimumSize: Size(64, den.controlLg), shape: shape),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: AppColorsDark.bgSunken,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.sm),
          borderSide: const BorderSide(color: AppColorsDark.borderStrong),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.sm),
          borderSide: const BorderSide(color: AppColorsDark.borderStrong),
        ),
      ),
    );
  }

  static ThemeData light({bool compact = false}) {
    const cs = _lightScheme;
    final den = compact ? AppDensity.compact : AppDensity.comfortable;
    final shape = RoundedRectangleBorder(borderRadius: BorderRadius.circular(AppRadius.sm));
    return ThemeData(
      colorScheme: cs,
      scaffoldBackgroundColor: AppColorsLight.bgCanvas,
      textTheme: AppText.theme(AppColorsLight.textPrimary, compact: compact),
      materialTapTargetSize: compact ? MaterialTapTargetSize.shrinkWrap : MaterialTapTargetSize.padded,
      visualDensity: compact ? VisualDensity.compact : VisualDensity.standard,
      extensions: const <ThemeExtension<dynamic>>[TradeColors.light],
      cardTheme: CardThemeData(
        color: cs.surfaceContainer,
        elevation: 0,
        surfaceTintColor: const Color(0x00000000),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.md),
          side: const BorderSide(color: AppColorsLight.borderSubtle),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(minimumSize: Size(64, den.controlLg), shape: shape),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          minimumSize: Size(64, den.controlLg),
          shape: shape,
          side: const BorderSide(color: AppColorsLight.borderStrong),
        ),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(minimumSize: Size(64, den.controlLg), shape: shape),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: AppColorsLight.bgSunken,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.sm),
          borderSide: const BorderSide(color: AppColorsLight.borderStrong),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.sm),
          borderSide: const BorderSide(color: AppColorsLight.borderStrong),
        ),
      ),
    );
  }
}

extension TradeColorsX on BuildContext {
  /// Null-safe: falls back to the palette matching the current brightness (no crash in tests / ad-hoc Theme()).
  TradeColors get tradeColors =>
      Theme.of(this).extension<TradeColors>() ??
      (Theme.of(this).brightness == Brightness.dark ? TradeColors.dark : TradeColors.light);
}
